package com.chubb.claims.claim;

import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.PastOrPresent;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;

/** Create request. Deliberately has no id / claimId: both are generated by the server. */
public record CreateClaimRequest(
        @NotBlank @Size(max = 200) String claimantName,
        @NotBlank @Email @Size(max = 254) String claimantEmail,
        @NotBlank @Pattern(regexp = "[A-Z]{2}", message = "must be a 2-letter upper-case market code, e.g. SG") String market,
        @NotNull ClaimType claimType,
        @NotBlank @Size(max = 2000) String description,
        @NotNull @PastOrPresent LocalDate incidentDate,
        @NotNull @Positive @Digits(integer = 17, fraction = 2) BigDecimal claimedAmount,
        @NotBlank @Pattern(regexp = "[A-Z]{3}", message = "must be a 3-letter upper-case ISO currency code, e.g. INR") String currency) {
}
